define(["jquery"],function($){"use strict";var Calculator={currentExpression:"0",mode:"scientific",init:function(){var self=this;$("#sat-btn-calculator").on("click",function(e){e.preventDefault();$("#sat-calculator-panel").toggleClass("d-none")});$("#sat-calc-close").on("click",function(){$("#sat-calculator-panel").addClass("d-none")});$("#sat-calc-mode-toggle").on("click",function(){if(self.mode==="scientific"){self.mode="graphing";$(this).text("Calc");$("#sat-calc-scientific").addClass("d-none");$("#sat-calc-graphing").removeClass("d-none");self.renderGraph()}else{self.mode="scientific";$(this).text("Graph");$("#sat-calc-graphing").addClass("d-none");$("#sat-calc-scientific").removeClass("d-none")}});$(".calc-btn").on("click",function(){var val=$(this).data("val");self.handleButton(val)});$("#sat-graph-plot-btn").on("click",function(){self.renderGraph()});self.setupDraggable()},normalizeExpression:function(raw){return String(raw).replace(/(\d)(x|sin|cos|tan|sqrt|log|ln|pi|\()/gi,"$1*$2").replace(/(\))(\d|x|sin|cos|tan|sqrt|log|ln|pi|\()/gi,"$1*$2").replace(/sin/g,"Math.sin").replace(/cos/g,"Math.cos").replace(/tan/g,"Math.tan").replace(/sqrt/g,"Math.sqrt").replace(/log/g,"Math.log10").replace(/ln/g,"Math.log").replace(/pi/g,"Math.PI").replace(/\be\b/g,"Math.E").replace(/\^/g,"**")},handleButton:function(val){var screen=$("#sat-calc-screen");if(val==="C"){this.currentExpression="0"}else if(val==="DEL"){if(this.currentExpression.length>1){this.currentExpression=this.currentExpression.slice(0,-1)}else{this.currentExpression="0"}}else if(val==="="){try{var expr=this.normalizeExpression(this.currentExpression);var result=eval(expr);this.currentExpression=typeof result==="number"&&!isNaN(result)?String(Number(result.toFixed(6))):"Error"}catch(e){this.currentExpression="Error"}}else{if(this.currentExpression==="0"||this.currentExpression==="Error"){this.currentExpression=String(val)}else{this.currentExpression+=String(val)}}screen.val(this.currentExpression)},renderGraph:function(){var canvas=document.getElementById("sat-graph-canvas");if(!canvas){return}var ctx=canvas.getContext("2d");var width=canvas.width;var height=canvas.height;ctx.clearRect(0,0,width,height);var originX=width/2;var originY=height/2;var scale=20;ctx.strokeStyle="#e2e8f0";ctx.lineWidth=1;for(var x=0;x<width;x+=scale){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,height);ctx.stroke()}for(var y=0;y<height;y+=scale){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(width,y);ctx.stroke()}ctx.strokeStyle="#64748b";ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,originY);ctx.lineTo(width,originY);ctx.stroke();ctx.beginPath();ctx.moveTo(originX,0);ctx.lineTo(originX,height);ctx.stroke();var rawFn=$("#sat-graph-function").val()||"x^2 - 4";var jsFn=this.normalizeExpression(rawFn);ctx.strokeStyle="#2563eb";ctx.lineWidth=2.5;ctx.beginPath();var firstPoint=true;for(var px=0;px<=width;px+=2){var mathX=(px-originX)/scale;try{var expr=jsFn.replace(/x/g,"("+mathX+")");var mathY=eval(expr);if(typeof mathY==="number"&&!isNaN(mathY)&&isFinite(mathY)){var py=originY-mathY*scale;if(firstPoint){ctx.moveTo(px,py);firstPoint=false}else{ctx.lineTo(px,py)}}else{firstPoint=true}}catch(e){firstPoint=true}}ctx.stroke()},setupDraggable:function(){var panel=$("#sat-calculator-panel");var handle=$("#sat-calc-drag-handle");var isDragging=false;var offset={x:0,y:0};handle.on("mousedown",function(e){isDragging=true;offset.x=e.clientX-panel.offset().left;offset.y=e.clientY-panel.offset().top});$(document).on("mousemove",function(e){if(isDragging){panel.css({left:e.clientX-offset.x+"px",top:e.clientY-offset.y+"px",right:"auto"})}});$(document).on("mouseup",function(){isDragging=false})}};return Calculator});